function sendToAuditService(envData) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify({
      timestamp: new Date().toISOString(),
      environment: envData
    });

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      }
    };

    const req = https.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`Audit log sent successfully. Status: ${res.statusCode}`);
        resolve();
      });
    });

    req.on('error', (error) => {
      console.error(`Failed to send audit log: ${error.message}`);
      // Continue with migration even if audit fails
      resolve();
    });

    req.write(data);
    req.end();
  });
}

