const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads and returns SQL migration files sorted by filename
 * @returns {Promise<Array<string>>} Array of migration filenames sorted in ascending order
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.review(migrationsDir, (err, files) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.log(`Migrations directory "${migrationsDir}" does not exist.`);
          resolve([]);
          return;
        }
        reject(err);
        return;
      }

      // Filter for SQL files only and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // Sort alphabetically (which works for numeric prefixes like 001, 002, etc.)

      resolve(sqlFiles);
    });
  });
}

/**
 * Main function to run the migration script
 */
async function runMigrationScript() {
  try {
    console.log('Starting database migration process...');
    console.log(`Looking for SQL migration files in: ${migrationsDir}`);
