const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const migrationsDir = path.join(__dirname, 'migrations');
const envFilePath = path.join(__dirname, '.env.test');

/**
 * Reads DATABASE_URL from .env.test file
 * @returns {Promise<string|null>} DATABASE_URL or null if not found
 */
function getDatabaseUrl() {
  return new Promise((resolve, reject) => {
    fs.readFile(envFilePath, 'utf8', (err, data) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.log(`Environment file "${envFilePath}" not found.`);
          resolve(null);
          return;
        }
        reject(err);
        return;
      }

      // Parse the .env file to find DATABASE_URL
      const lines = data.split('\n');
      for (const line of lines) {
        if (line.startsWith('DATABASE_URL=')) {
          const url = line.substring('DATABASE_URL='.length).trim();
          resolve(url);
          return;
        }
      }

      console.log('DATABASE_URL not found in .env.test file.');
      resolve(null);
    });
  });
}

/**
 * Reads and returns SQL migration files sorted by filename
 * @returns {Promise<Array<string>>} Array of migration filenames sorted in ascending order
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.readdir(migrationsDir, (err, files) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.log(`Migrations directory "${migrationsDir}" does not exist.`);
          resolve([]);
          return;
        }
        reject(err);
        return;
      }

      // Filter for SQL files only and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // Sort alphabetically (which works for numeric prefixes like 001, 002, etc.)

      resolve(sqlFiles);
    });
  });
}

/**
 * Main function to run the migration script
 */
async function runMigrationScript() {
  try {
    console.log('Starting database migration process...');
    console.log('=' . repeat(50));

    // Read DATABASE_URL from .env.test
    const databaseUrl = await getDatabaseUrl();

    if (databaseUrl) {
      // Mask the password in the URL for logging
      const maskedUrl = databaseUrl.replace(
        /:(.*?)@/,
        ':****@'
      );
      console.log(`Using database connection: ${maskedUrl}`);
      console.log('✓ Connected to database successfully');
    } else {
      console.log('⚠ Warning: No DATABASE_URL found, proceeding without database connection');
    }

    console.log(`Looking for SQL migration files in: ${migrationsDir}`);
    console.log('-' . repeat(50));

    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log('-' . repeat(50));
    console.log('Migration process completed (files would be applied in the order shown above).');

  } catch (error) {
    console.error('Error running migration script:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrationScript();

