const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads and returns sorted migration files from the migrations directory
 * @returns {Promise<string[]>} Sorted array of migration filenames
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.review(migrationsDir, (err, files) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.log('Migrations directory does not exist. Creating it...');
          fs.mkdirSync(migrationsDir, { recursive: true });
          resolve([]);
          return;
        }
        reject(err);
        return;
      }

      // Filter for SQL files only and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // Natural sort for numbered migrations

      resolve(sqlFiles);
    });
  });
}

/**
 * Main function to run the migration script
 */
async function runMigrationScript() {
  try {
    console.log('Starting migration script...');
    console.log(`Reading SQL files from: ${migrationsDir}\n`);

    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
