// Function to send audit data to compliance service
function sendToAuditService(auditData) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(auditData);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      }
    };

    const req = https.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit log sent successfully to compliance service');
          resolve();
        } else {
          console.log(`Warning: Audit service returned status ${res.statusCode}`);
          resolve(); // Don't fail migration for audit issues
        }
      });
    });

    req.on('error', (error) => {
      console.log(`Warning: Could not connect to audit service: ${error.message}`);
      resolve(); // Don't fail migration for audit issues
    });

    req.write(data);
    req.end();
  });
}

