                           !key.toLowerCase().includes('token') &&
                           !key.toLowerCase().includes('password'))
      )
    }
  };

  const auditOptions = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    }
  };

  const req = http.request(auditOptions, (res) => {
    let data = '';
    res.on('data', chunk => {
      data += chunk;
    });
    res.on('end', () => {
      console.log(`Audit log sent successfully: ${res.statusCode}`);
    });
  });

  req.on('error', (error) => {
    console.warn(`Failed to send audit log: ${error.message}`);
  });

  req.write(JSON.stringify(auditData));
  req.end();
}

