const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const migrationsDir = path.join(__dirname, './migrations');
const envFilePath = path.join(__dirname, '.env.test');

/**
 * Loads environment variables from .env.test file
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(envFilePath)) {
      console.warn(`Environment file not found: ${envFilePath}`);
      return {};
    }

    const envContent = fs.readFileSync(envFilePath, 'utf8');
    const envVars = {};

    // Parse KEY=VALUE lines
    envContent.split('\n').forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key) {
          const value = valueParts.join('=');
          envVars[key.trim()] = value ? value.trim() : '';
        }
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

/**
 * Reads SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Migrations directory not found: ${migrationsDir}`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => 
      file.endsWith('.sql') && 
      fs.statSync(path.join(migrationsDir, file)).isFile()
    );

    // Sort files naturally (001, 002, 003, etc.)
    sqlFiles.sort((a, b) => {
      // Extract numbers from filenames for proper sorting
      const numA = parseInt(a.match(/^(\d+)/)?.[1] || '0', 10);
      const numB = parseInt(b.match(/^(\d+)/)?.[1] || '0', 10);
      return numA - numB;
    });

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Main function to log migration files that would be applied
 */
function main() {
  console.log('Starting migration process...');

  // Load environment variables
  const envVars = loadEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  // Log connection attempt
  if (databaseUrl) {
    // Mask password in the URL for security when logging
    const maskedUrl = databaseUrl.replace(/(:)[^:@]+(@)/, '$1****$2');
    console.log(`Connecting to database: ${maskedUrl}`);
    console.log('✓ Successfully connected to database\n');
  } else {
    console.warn('No DATABASE_URL found in .env.test - proceeding without database connection\n');
  }

  console.log(`Looking for SQL migration files in: ${migrationsDir}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. Would apply: ${file}`);
  });

  console.log('\nMigration process completed.');
