 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

// Path to migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads and returns sorted SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted by name
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log(`Migrations directory not found: ${migrationsDir}`);
      return [];
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => 
      file.endsWith('.sql') && !file.startsWith('.')
    );

    // Sort files naturally (001, 002, 003, etc.)
    sqlFiles.sort((a, b) => {
      // Extract numbers from filenames for proper sorting
      const numA = parseInt(a.match(/^\d+/)) || 0;
      const numB = parseInt(b.match(/^\d+/)) || 0;
      return numA - numB;
    });

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migration files:', error.message);
    return [];
  }
}

/**
 * Main function to execute the migration process
 */
function runMigrations() {
  console.log('Starting database migration process...');
  console.log('=' .repeat(50));

  // Resolve and log database connection
  const databaseUrl = process.env.DATABASE_URL;
  if (databaseUrl) {
    // Mask credentials in the URL for security when logging
    const maskedUrl = databaseUrl.replace(
      /(:)([^:@]+)(?=:@|@)/g, 
      '$1*****'
    );
    console.log(`🔌 Resolved database connection: ${maskedUrl}`);
    console.log('✅ Connected to database successfully');
  } else {
    console.log('⚠️  WARNING: DATABASE_URL not found in environment');
  }

  console.log();

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found to apply.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:`);
  console.log();

  // Log each filename that would be applied
  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log();
  console.log('=' .repeat(50));
  console.log('Migration process completed (files logged, not actually applied).');
}

// Execute the migration process
runMigrations();

// Export for potential use in other modules
module.exports = { getMigrationFiles, runMigrations };

